#include <cctype>
#include <cstdio>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>
namespace {
struct Var { std::string type; };
std::string trim(std::string s) { while(!s.empty()&&std::isspace((unsigned char)s.front()))s.erase(s.begin()); while(!s.empty()&&std::isspace((unsigned char)s.back()))s.pop_back(); return s; }
bool starts(const std::string&s,const std::string&p){return s.rfind(p,0)==0;}
bool ident(const std::string&s){if(s.empty()||!(std::isalpha((unsigned char)s[0])||s[0]=='_'))return false;for(char c:s)if(!(std::isalnum((unsigned char)c)||c=='_'))return false;return true;}
bool integer(const std::string&s){if(s.empty())return false;size_t i=(s[0]=='-'||s[0]=='+')?1:0;if(i==s.size())return false;for(;i<s.size();++i)if(!std::isdigit((unsigned char)s[i]))return false;return true;}
bool literal(const std::string&s,std::string&v){if(s.size()<2||s.front()!='"'||s.back()!='"')return false;v.clear();for(size_t i=1;i+1<s.size();++i){char c=s[i];if(c=='\\'){if(++i+1>s.size())return false;c=s[i];switch(c){case 'n':v+='\n';break;case 't':v+='\t';break;case 'r':v+='\r';break;case '\\':v+='\\';break;case '"':v+='"';break;default:return false;}}else v+=c;}return true;}
std::string cs(const std::string&s){std::string o="\"";for(unsigned char c:s){switch(c){case '\\':o+="\\\\";break;case '"':o+="\\\"";break;case '\n':o+="\\n";break;case '\r':o+="\\r";break;case '\t':o+="\\t";break;default:if(c<32||c>=127){char b[5];std::snprintf(b,sizeof b,"\\%03o",c);o+=b;}else o+=(char)c;}}return o+"\"";}
bool val(const std::string&raw,std::string&type,std::string&v){auto s=trim(raw);if(integer(s)){type="int";v=s;return true;}if(literal(s,v)){type="string";return true;}return false;}
bool compile(const std::string&inpath,const std::string&outpath){std::ifstream in(inpath);if(!in){std::cerr<<"xc-codegen: cannot open input\n";return false;}std::vector<std::string> lines;for(std::string l;std::getline(in,l);)lines.push_back(l);std::ofstream o(outpath);if(!o){std::cerr<<"xc-codegen: cannot write output\n";return false;}std::map<std::string,Var> vars;std::vector<bool> elses;o<<"/* Generated by XC compiler. */\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <limits.h>\nint main(void) {\n";bool finished=false;
#define SYNTAX() do { std::cerr<<"xc-codegen: line "<<i+1<<": invalid syntax or unsupported value\n"; return false; } while(0)
for(size_t i=0;i<lines.size();++i){std::string s=trim(lines[i]);if(s.empty()||s[0]=='#')continue;if(starts(s,"program ")){std::string n;if(!literal(trim(s.substr(8)),n))SYNTAX();continue;}
if(starts(s,"let ")){auto eq=s.find('=');if(eq==std::string::npos)SYNTAX();std::string n=trim(s.substr(4,eq-4)),t,v;if(!ident(n)||vars.count(n)||!val(s.substr(eq+1),t,v))SYNTAX();vars[n]={t};if(t=="int")o<<"  long long "<<n<<" = "<<v<<"LL;\n";else o<<"  char "<<n<<"[] = "<<cs(v)<<";\n";continue;}
if(starts(s,"add ")){std::istringstream ss(s.substr(4));std::string n,a,x;if(!(ss>>n>>a)||(ss>>x)||!vars.count(n)||vars[n].type!="int"||!integer(a))SYNTAX();o<<"  "<<n<<" += "<<a<<"LL;\n";continue;}
if(starts(s,"say ")){std::string v;if(!literal(trim(s.substr(4)),v))SYNTAX();o<<"  puts("<<cs(v)<<");\n";continue;}
if(starts(s,"show ")){std::string n=trim(s.substr(5));if(!vars.count(n))SYNTAX();if(vars[n].type=="int")o<<"  printf(\"%lld\\n\", "<<n<<");\n";else o<<"  puts("<<n<<");\n";continue;}
if(starts(s,"ask ")){std::string n=trim(s.substr(4));if(!ident(n)||vars.count(n))SYNTAX();vars[n]={"string"};o<<"  char "<<n<<"[256] = {0};\n  if (!fgets("<<n<<", sizeof "<<n<<", stdin)) "<<n<<"[0] = '\\0';\n  "<<n<<"[strcspn("<<n<<", \"\\r\\n\")] = '\\0';\n";continue;}
if(starts(s,"if ")){auto e=trim(s.substr(3));auto op=e.find("==");if(op==std::string::npos)SYNTAX();std::string n=trim(e.substr(0,op)),t,v;if(!vars.count(n)||!val(e.substr(op+2),t,v)||vars[n].type!=t)SYNTAX();if(t=="int")o<<"  if ("<<n<<" == "<<v<<"LL) {\n";else o<<"  if (strcmp("<<n<<", "<<cs(v)<<") == 0) {\n";elses.push_back(false);continue;}
if(s=="else"){if(elses.empty()||elses.back())SYNTAX();o<<"  } else {\n";elses.back()=true;continue;}
if(s=="end"){if(elses.empty())SYNTAX();o<<"  }\n";elses.pop_back();continue;}
if(s=="finish"){if(!elses.empty())SYNTAX();o<<"  return 0;\n";finished=true;break;}
std::cerr<<"xc-codegen: line "<<i+1<<": unsupported statement\n";return false;}
#undef SYNTAX
if(!elses.empty()){std::cerr<<"xc-codegen: unclosed if\n";return false;}if(!finished)o<<"  return 0;\n";o<<"}\n";return (bool)o;}
}
int main(int argc,char**argv){if(argc!=4||std::string(argv[1])!="build"){std::cerr<<"usage: xc-codegen build input.xc output.c\n";return 2;}return compile(argv[2],argv[3])?0:1;}
